import re,yaml,collections
src=open('scripts/db.py').read()
sm=yaml.safe_load(open('governance/stage-map.yaml'))['tables']
i=src.index('if args.command == "migrate"')
body=src[i:]
parts=re.split(r'\n    (?:el)?if args\.command == "([\w-]+)":',"\n    if args.command == \"migrate\":"+body[len('if args.command == "migrate":'):])
# parts: ['', name, text, name, text...]
res={}
for k in range(1,len(parts),2):
    name,text=parts[k],parts[k+1]
    ts=set(m for m in re.findall(r'(?:INSERT(?:\s+OR\s+\w+)?\s+INTO|UPDATE|DELETE\s+FROM)\s+"?([a-z_]+)"?',text,re.I) if m in sm)
    # called helpers
    calls=set(re.findall(r'\b((?:insert|do|cmd|add|amend|record|update|resolve|raise|retire|merge|rename|revoke|annotate|mint|derive|relate|adjudicate|observe|decline|link|supersede|set|dispose|close|reattribute|unlink|correct)_\w+)\(',text))
    res[name]=(ts,calls)
# resolve helper functions
fn={m.group(1):m.start() for m in re.finditer(r'^def (\w+)\(',src,re.M)}
order=sorted(fn.items(),key=lambda x:x[1])
def fbody(n):
    s=fn[n]; nxt=[p for _,p in order if p>s]; return src[s:(nxt[0] if nxt else len(src))]
def deep(n,seen):
    if n in seen or n not in fn: return set()
    seen.add(n); b=fbody(n)
    t=set(m for m in re.findall(r'(?:INSERT(?:\s+OR\s+\w+)?\s+INTO|UPDATE|DELETE\s+FROM)\s+"?([a-z_]+)"?',b,re.I) if m in sm)
    for c in re.findall(r'\b([a-z_]\w+)\(',b):
        if c in fn and c!=n: t|=deep(c,seen)
    return t
for name,(ts,calls) in res.items():
    t=set(ts)
    for c in re.findall(r'\b([a-z_]\w+)\(',parts[parts.index(name)+1]):
        if c in fn: t|=deep(c,set())
    stg=sorted({sm[x] for x in t})
    print(f"{name:26}|{','.join(sorted(t)) or '-'}|{','.join(stg)}")
